require_role(['administrador','coordinador_mg','auxiliar_mg','docente','estudiante']);requerir_permiso('mg.informes.ver');$m=new MgSeguimientoModel($pdo);$bit=new MgBitacoraModel($pdo);$rol=user_role();$uid=(int)$_SESSION['id_usuario'];
